import 'package:flutter/material.dart';
import '../../core/theme/colors.dart';
class PromotionCard extends StatelessWidget { const PromotionCard({super.key, required this.days, required this.price, this.selected = false}); final int days; final double price; final bool selected; @override Widget build(BuildContext context) => Card(shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14), side: BorderSide(color: selected ? AppColors.primary : AppColors.border, width: selected ? 2 : 1)), child: Padding(padding: const EdgeInsets.all(14), child: Column(children: [Text('$days days', style: const TextStyle(fontWeight: FontWeight.w800)), Text('NPR ${price.toStringAsFixed(0)}'), if (days == 30) const Text('Best value', style: TextStyle(color: AppColors.accent))]))); }
